    body.behavior-immersive {
        padding: 0 !important;
        margin: 0 !important;
        overflow-x: hidden !important;
    }
    body.behavior-immersive .main-wrapper { 
        height: 100vh;
        overflow: hidden;
        display: block;
        padding: 0 !important;
        margin: 0 !important;
        max-width: none !important;
    }
