        display: block;
        height: 100vh;
        padding: 0 !important;
        margin: 0 !important;
        width: 100vw !important;
        left: 0 !important;
    }
    body.behavior-immersive .image-panel {
        position: fixed;
        top: 0; left: 0;
        width: 100vw; height: 100vh;
        z-index: 1;
        max-width: none;
        border: none !important;
        padding: 0 !important;
        background: black;
    }
    body.behavior-immersive .image-container, 
    body.behavior-immersive .scene-image {
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        padding: 0 !important;
        width: 100vw !important;
        height: 100vh !important;
    }
    body.behavior-immersive .text-panel {
        position: absolute;
        bottom: 0; left: 0;
        width: 100vw !important;
        z-index: 2;
        background: none;
        padding: 0 !important;
        margin: 0 !important;
        flex: none;
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
        height: 100vh;
        pointer-events: none;
    }
    body.behavior-immersive .scene-description {
        background: linear-gradient(to top, rgba(0,0,0,0.98) 75%, transparent 100%) !important;
        display: flex !important;
        flex-direction: column !important;
        justify-content: flex-end !important;
        padding: 100px 15px 10px 15px !important; 
        max-height: 60vh !important; 
        min-height: 35vh !important; 
        width: 100vw !important;
        flex-grow: 0;
        border-radius: 0;
        pointer-events: auto;
        box-sizing: border-box !important;
        left: 0 !important;
        margin: 0 !important;
        font-size: 0.85em !important;
    }
    body.behavior-immersive .action-bar {
        background: rgba(0,0,0,0.98) !important; 
        border-top: none !important;
        padding: 2px 15px 15px 15px !important; 
        margin-top: 0 !important;
        pointer-events: auto;
        width: 100vw !important;
        box-sizing: border-box !important;
        left: 0 !important;
        margin: 0 !important;
    }

    body.behavior-immersive .action-popup:not(.hidden) {
        background: rgba(0,0,0,0.98) !important; 
        border: none !important;
        margin: 0 !important; 
